From 844b7dcd6e7ff87304c4decf96f6909770803aa0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:16:24 +0100
Subject: [PATCH] applet: show signal strength in device details

The applet gave no way to tell how far a device is, unlike Wi-Fi in the
network applet. The device details now show the signal strength as a
percentage whenever BlueZ reports an RSSI, which it does while scanning.

BUG: 478431
---
 src/applet/qml/DeviceItem.qml | 13 +++++++++++++
 1 file changed, 13 insertions(+)

diff --git a/src/applet/qml/DeviceItem.qml b/src/applet/qml/DeviceItem.qml
index e750926a..28e8e403 100644
--- a/src/applet/qml/DeviceItem.qml
+++ b/src/applet/qml/DeviceItem.qml
@@ -209,6 +209,14 @@ PlasmaExtras.ExpandableListItem {
         }
     }

+    // BlueZ only reports RSSI while the adapter is discovering
+    property int __rssi: model.Rssi
+    on__RssiChanged: {
+        if (expanded) {
+            createContent();
+        }
+    }
+
     function boolToString(value: bool): string {
         return value ? i18n("Yes") : i18n("No");
     }
@@ -240,6 +248,11 @@ PlasmaExtras.ExpandableListItem {
         details.push(i18n("Adapter"));
         details.push(adapterName(model.Adapter));

+        if (model.Rssi !== -32768) {
+            details.push(i18n("Signal Strength"));
+            details.push(i18nc("Bluetooth signal strength percentage indicator", "%1%", Math.max(0, Math.min(100, 2 * (model.Rssi + 100)))));
+        }
+
         currentDeviceDetails = details;
     }

-- 
